	"encoding/json"
	"errors"
	"fmt"
	"strings"

	"github.com/gzhysuiioo/indexroom-analytics/indexroom"
)

func exportString(idx *indexroom.Index) string {
	var b bytes.Buffer
	if err := idx.Export(&b); err != nil {
		panic(err)
	}
	return b.String()
}

func main() {
	// 1. What does the plain JSON decoder do with an invalid raw byte?
	doc := `{"version":1,"tip":1,"blocks":[{"height":1,"hash":"h` + "\xff" + `1","parent":"g","txs":[]}]}`
	var top struct {
		Blocks []struct {
			Hash string `json:"hash"`
		} `json:"blocks"`
	}
