	var s string
	_ = json.Unmarshal([]byte(`"b\uD83D"`), &s)
	fmt.Printf("plain decoder lone high: %q bytes=% x\n\n", s, []byte(s))

	// 3. Valid identifiers
	good := `{"version":1,"tip":2,"blocks":[{"height":1,"hash":"h1","parent":"g","txs":["tx-😀","�","�","","tx-😀"]},{"height":2,"hash":"😀","parent":"h1","txs":[]}]}`
	idx2 := indexroom.New()
