		if err := idx3.Append(b); err != nil {
			panic(err)
		}
	}
	bad2 := `{"version":1,"tip":2,"blocks":[` +
		`{"height":1,"hash":"new-1","parent":"genesis","txs":["付款","付"]},` +
		`{"height":2,"hash":"new-2","parent":"new-1","txs":["x` + "\xff" + `"]}]}`
	err = idx3.Restore(strings.NewReader(bad2))
	fmt.Printf("late bad byte: err=%v\n  isInvalid=%v tip=%d\n", err, errors.Is(err, indexroom.ErrInvalidSnapshot), idx3.Tip)
