	// 不同；但解码后的数据（标识、次序、位置）完全一致，这不是数据损坏。
	exported := exportString(idx)
	fmt.Println("操作 2：再次导出（转义写法改变，但数据一致）")
	fmt.Printf("  再次导出：%s\n", exported)
	fmt.Printf("  与输入逐字节一致：%v（输入用了 \\uXXXX 转义，导出直接写出字符）\n",
		exported == inputV1)
	fmt.Print("  数据仍一致的核对：")
	showQuery(idx, "tx-😀")
	fmt.Println()

