	var rewrittenByte string
	_ = json.Unmarshal([]byte("\"x\xff\""), &rewrittenByte)
	var rewrittenSurrogate string
	_ = json.Unmarshal([]byte(`"b\ud83d"`), &rewrittenSurrogate)
	fmt.Println("操作 5：标准库解码器会怎样“容错”（Restore 不采用这种行为）")
	fmt.Printf("  含非法字节的 \"x\\xff\" 直接解码会变成 %q；孤立高代理项 \"b\\ud83d\" 会变成 %q\n",
		rewrittenByte, rewrittenSurrogate)
	fmt.Println("  坏字节/孤立代理项都被悄悄替换成 U+FFFD，会让不同标识无法区分；")
	fmt.Println("  真正写入的 U+FFFD（含合法转义 \\ufffd）是正常字符，与这种替换无关。")
