		{
			"v1 高度2 交易标识0 含非法 UTF-8 字节",
			v1Doc(`{"height":2,"hash":"new-2","parent":"new-1","txs":["x` + "\xff" + `"]}`),
		},
		{
			"v1 高度2 哈希含非法 UTF-8 字节",
			v1Doc(`{"height":2,"hash":"h` + "\xff" + `","parent":"new-1","txs":[]}`),
		},
		{"v1 高度2 交易标识0 只有高代理项（缺少紧跟的低代理项）",
			v1Doc(`{"height":2,"hash":"new-2","parent":"new-1","txs":["\ud800"]}`)},
		{"v1 高度2 父哈希是孤立的低代理项",
			v1Doc(`{"height":2,"hash":"new-2","parent":"\udc00","txs":[]}`)},
		{"v2 高度2 交易标识0 代理项对顺序颠倒（低代理项在前）",
