		unchanged := target.Tip == 1 && exportString(target) == before
		fmt.Printf("  %s：\n    err=%v\n", tc.name, err)
		fmt.Printf("    errors.Is(err, ErrInvalidSnapshot)=%v；拒绝后链顶仍为1且导出未变=%v\n",
