	fmt.Printf("  err=%v\n", err)
	fmt.Printf("  errors.Is(err, 读取错误)=%v errors.Is(err, ErrInvalidSnapshot)=%v；链顶仍为 tip=%d，导出未变=%v\n",
		errors.Is(err, readFault), errors.Is(err, indexroom.ErrInvalidSnapshot),
