// v2Doc 与 v1Doc 对应，但拼出版本 2 快照（每块带 timestamp），
// 用来证明版本 1 与版本 2 的字符串编码规则完全相同。
func v2Doc(block2 string) string {
	return `{"version":2,"tip":2,"blocks":[` +
		`{"height":1,"hash":"new-1","parent":"genesis","txs":["新交易"],"timestamp":null},` +
		block2 + `]}`
