		Height: 1, Hash: "keep-1", Parent: "genesis", Txs: []string{"付款", "😀"},
	}); err != nil {
		panic(err)
	}
	before := exportString(target)
	fmt.Println("操作 4：现有链（非法恢复的目标，恢复前后都应保持原状）")
	fmt.Printf("  %s\n", before)
