		idx.Blocks[1].Hash, idx.Blocks[1].Parent, idx.Blocks[1].Txs)
	fmt.Printf("    高度2 hash=%q parent=%q txs=%q\n",
		idx.Blocks[2].Hash, idx.Blocks[2].Parent, idx.Blocks[2].Txs)
